import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.DDEX3mHW.js";const p=JSON.parse('{"title":"导入节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/import.md","filePath":"guide/import.md","lastUpdated":1792223362000}'),r={name:"guide/import.md"};function l(s,e,d,n,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="导入节点" tabindex="-1">导入节点 <a class="header-anchor" href="#导入节点" aria-label="Permalink to &quot;导入节点&quot;">​</a></h1><p>在 <strong>落地</strong> 页点击 <strong>导入</strong>，可以把不是面板部署的节点（脚本搭的、没装 agent 的机器、机场节点）加进来，用来对接中转和加入订阅。转换规则参考 Sub-Store：所有格式先转成 Mihomo（Clash Meta）节点格式保存，再按订阅格式输出，参数不会丢失。</p><h2 id="支持的输入" tabindex="-1">支持的输入 <a class="header-anchor" href="#支持的输入" aria-label="Permalink to &quot;支持的输入&quot;">​</a></h2><ul><li>分享链接（每行一个）：<code>ss://</code>（含 obfs / v2ray-plugin / shadow-tls 插件）、<code>vmess://</code>（v2rayN 格式）、<code>vless://</code>（含 Reality、WS、gRPC、H2、XHTTP）、<code>trojan://</code>、<code>hysteria2://</code> / <code>hy2://</code>、<code>tuic://</code>、<code>anytls://</code>、<code>socks5://</code></li><li>base64 订阅内容</li><li>Clash / Mihomo 配置（读取 <code>proxies</code>）</li><li>sing-box 配置（读取 <code>outbounds</code>）</li><li>Surge / Loon 节点行，例如 <code>名称 = snell, 1.2.3.4, 6160, psk=..., version=4</code></li><li>订阅地址（<code>https://...</code>）：面板服务器会以 Mihomo 的身份去下载，拿到的通常是参数最完整的 Clash 配置。打开 <strong>定时同步</strong>（默认打开）会存成 <a href="./subscription#订阅源">订阅源</a>，按时更新；关掉则只导入一次</li></ul><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>暂不支持 WireGuard、SSR、Hysteria v1 等类型，导入时会逐条提示</li><li>经中转连接时，原节点用域名连接的，会自动把域名保留为 TLS SNI 和 WebSocket Host；Hysteria2 端口跳跃只在直连线路上保留</li><li>面板不会部署、修改这些节点，也没有流量统计、白名单、换密钥等功能</li><li>原节点的地址或参数变了，点击该节点 → <strong>编辑</strong>，修改地址或粘贴新的链接替换参数，相关中转会自动指向新地址</li><li>勾选“订阅里只保留中转线路”后，订阅和分享中不再包含直连线路（该节点没有中转时就不会出现在订阅里）</li><li>删除只会删除面板里的记录和相关中转，不影响原服务器</li><li>同一个地址和端口不会重复导入</li></ul><h2 id="连通性检测" tabindex="-1">连通性检测 <a class="header-anchor" href="#连通性检测" aria-label="Permalink to &quot;连通性检测&quot;">​</a></h2><p>面板服务器每 3 分钟会连一次所有导入的节点，落地页上方的 <strong>检测</strong> 按钮可以马上测一遍：</p><ul><li>连得上：绿点，后面显示延迟（例如 <code>· 85 ms</code>）</li><li>连不上：红点，并显示原因（连接超时、域名解析失败、无法连接）</li></ul><p>检测是从 <strong>面板服务器</strong> 发起的 TCP 连接，只能作为参考：面板连不上不代表中转机也连不上，反之亦然。Hysteria2、TUIC 只用 UDP，无法这样检测，不显示状态。开启 <a href="./notify">通知</a> 后，导入节点连续两次连不上会推送提醒。</p><h2 id="对接中转" tabindex="-1">对接中转 <a class="header-anchor" href="#对接中转" aria-label="Permalink to &quot;对接中转&quot;">​</a></h2><p>导入后的节点和面板部署的入站一样：点击节点 → <strong>中转</strong> → 选择隧道即可，端口转发和隧道转发（包括经 IX 的多跳）都可以用。见 <a href="./relay">对接中转</a>。</p>',12)])])}const g=o(r,[["render",l]]);export{p as __pageData,g as default};
